package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for MathUtils.factorialDouble
 */
public class MathUtils_factorialDouble_TriageGen2Test {

    private static final double DELTA = 1e-10;



    @Test
    public void testFactorialDouble_SmallPositive() {
        // 1! = 1
        assertEquals(1.0, MathUtils.factorialDouble(1), DELTA);
        // 3! = 6
        assertEquals(6.0, MathUtils.factorialDouble(3), DELTA);
        // 5! = 120
        assertEquals(120.0, MathUtils.factorialDouble(5), DELTA);
    }






}

package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for MathUtils.factorialDouble
 */
public class MathUtils_factorialDouble_TriageGen2Test {

    private static final double DELTA = 1e-10;





    @Test
    public void testFactorialDouble_LargeValue() {
        // 10! = 3628800
        assertEquals(3628800.0, MathUtils.factorialDouble(10), DELTA);
        // 20! is large but fits in double
        // 20! = 2432902008176640000
        assertEquals(2.43290200817664E18, MathUtils.factorialDouble(20), 1e7);
    }




}

